{
    "predictors": [
        {
            "name": "Supplier Network Centrality",
            "construction": "Calculate the centrality of a firm's supplier network using data from supplier-disclosure filings and industry reports. Sum the normalized influence scores of direct and indirect supplier connections.",
            "rationale": "Firms with more central positions in supply networks may benefit from better information flows and negotiation power, leading to superior returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Intellectual Property Growth",
            "construction": "Measure the annual growth rate of the number of granted patents for each firm using USPTO data over the past five years.",
            "rationale": "Firms with rapid growth in intellectual property may be innovating more effectively, leading to higher future profitability and stock returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Satisfaction Index",
            "construction": "Construct an index based on employee satisfaction surveys from third-party providers, averaged over the past year for each firm.",
            "rationale": "Higher employee satisfaction can lead to increased productivity and retention, which may improve company performance and stock returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "ESG Disclosure Quality",
            "construction": "Evaluate the quality of a firm's ESG (Environmental, Social, Governance) disclosures using a scoring system based on completeness and detail, over the past year.",
            "rationale": "Better ESG disclosure might indicate a firm's commitment to sustainable practices, which could enhance reputation and long-term growth prospects.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Product Recall Frequency",
            "construction": "Count the number of product recalls a firm has issued in the past three years, using data from the Consumer Product Safety Commission.",
            "rationale": "Firms with fewer recalls may have superior quality control and risk management, potentially translating to better financial performance.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "CEO Media Sentiment",
            "construction": "Analyze the sentiment of media articles mentioning the firm's CEO using a text analysis tool, averaged over the past year.",
            "rationale": "Positive media sentiment towards a CEO may reflect confidence in leadership and future firm performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Concentration Risk",
            "construction": "Calculate the proportion of a firm's revenue attributable to its top five customers using the latest annual report.",
            "rationale": "High customer concentration can pose significant risks, potentially leading to volatility and lower returns if key customers are lost.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Foreign Revenue Exposure",
            "construction": "Determine the percentage of total revenue derived from foreign markets using geographic segment reporting in financial statements.",
            "rationale": "Firms with greater foreign revenue exposure may benefit from international growth opportunities and diversification.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Board Diversity Score",
            "construction": "Score firms based on the diversity of their board of directors in terms of gender, ethnicity, and expertise using annual reports.",
            "rationale": "Diverse boards may enhance decision-making and oversight, potentially leading to better strategic outcomes and returns.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Social Media Engagement",
            "construction": "Measure the level of engagement (likes, shares, comments) with a firm's social media posts in the past year.",
            "rationale": "High social media engagement can indicate strong brand presence and customer interaction, which may translate into higher sales and stock performance.",
            "higher_returns_for": "high values of the measure"
        }
    ]
}
